// Input = all rows from "Read All Companies" (one item per company).
const companies = $input.all().map(i => i.json);
const pendingCompanyNames = companies
  .filter(c => (c.Status || '').trim().toLowerCase() !== 'done')
  .map(c => (c['Company Name'] || '').trim().toLowerCase());

// Full accumulated candidate list from "Fetch Full Accumulated Result".
let candidates = $('Fetch Full Accumulated Result').first().json;
if (candidates && !Array.isArray(candidates)) {
  candidates = candidates.data || candidates.rows || candidates.results || [];
}
if (!Array.isArray(candidates)) candidates = [];

const filtered = candidates.filter(c => {
  const name = (c.companyName || '').trim().toLowerCase();
  return pendingCompanyNames.includes(name);
});

return filtered.map((c) => ({ json: c }));

