const responseText = $json.choices[0].message.content;
let parsed;
try {
  parsed = JSON.parse(responseText);
} catch (e) {
  parsed = { score: 0, seniority: 'Other', priority: 'Skip', reason: 'Could not parse LLM response' };
}
const candidate = $('Filter To Pending Companies').item.json;
return [{
  json: {
    Company: candidate.companyName,
    Name: candidate.fullName,
    Designation: candidate.title,
    Seniority: parsed.seniority,
    LinkedInURL: candidate.profileUrl,
    Score: parsed.score,
    Priority: parsed.priority,
    Reason: parsed.reason,
    Activity: 'Unknown',
    Status: parsed.score >= 70 ? 'Auto-Approved' : 'Needs Review'
  }
}];

const items = $input.all();
const byCompany = {};
for (const item of items) {
  const company = item.json.Company || 'Unknown';
  if (!byCompany[company]) byCompany[company] = [];
  byCompany[company].push(item);
}

const result = [];
for (const company of Object.keys(byCompany)) {
  const top4 = byCompany[company]
    .sort((a, b) => (b.json.Score || 0) - (a.json.Score || 0))
    .slice(0, 4);
  result.push(...top4);
}
return result;
